struct SelfTestModeScope {
    SelfTestModeScope() : previous(gRunningSelfTest), previousPresentation(gPresentationMode) {
        // Historical host fixtures explicitly exercise Legacy. The dedicated
        // V2 fixture selects its mode after entering this isolated test scope.
        if (!previous) gPresentationMode = PresentationMode::LegacyChild;
        gRunningSelfTest = true;
    }
    ~SelfTestModeScope() {
        gRunningSelfTest = previous;
        gPresentationMode = previousPresentation;
    }
    bool previous;
    PresentationMode previousPresentation;
};
