enum class ManagedPathState {
    Exists,
    NotFound,
    AccessDenied,
    Unavailable,
    Unknown,
};

struct ManagedPathProbe {
    ManagedPathState state = ManagedPathState::Unknown;
    DWORD win32Error = ERROR_SUCCESS;
};

ManagedPathState ClassifyManagedPathWin32Error(DWORD error) {
    switch (error) {
    case ERROR_FILE_NOT_FOUND:
    case ERROR_PATH_NOT_FOUND:
        return ManagedPathState::NotFound;
    case ERROR_ACCESS_DENIED:
    case ERROR_SHARING_VIOLATION:
    case ERROR_LOCK_VIOLATION:
    case ERROR_PRIVILEGE_NOT_HELD:
        return ManagedPathState::AccessDenied;
    case ERROR_INVALID_DRIVE:
    case ERROR_NOT_READY:
    case ERROR_DEVICE_NOT_CONNECTED:
    case ERROR_NO_SUCH_DEVICE:
    case ERROR_IO_DEVICE:
    case ERROR_BAD_NETPATH:
    case ERROR_BAD_NET_NAME:
    case ERROR_NETWORK_UNREACHABLE:
    case ERROR_HOST_UNREACHABLE:
    case ERROR_NETNAME_DELETED:
    case ERROR_NO_NETWORK:
    case ERROR_CONNECTION_UNAVAIL:
    case ERROR_UNEXP_NET_ERR:
    case ERROR_REM_NOT_LIST:
        return ManagedPathState::Unavailable;
    default:
        return ManagedPathState::Unknown;
    }
}

ManagedPathProbe QueryManagedPath(const std::wstring& path) {
    if (path.empty()) {
        return {ManagedPathState::Unknown, ERROR_INVALID_PARAMETER};
    }
    SetLastError(ERROR_SUCCESS);
    if (GetFileAttributesW(path.c_str()) != INVALID_FILE_ATTRIBUTES) {
        return {ManagedPathState::Exists, ERROR_SUCCESS};
    }
    const DWORD error = GetLastError();
    return {ClassifyManagedPathWin32Error(error), error};
}

const char* ManagedPathStateName(ManagedPathState state) {
    switch (state) {
    case ManagedPathState::Exists: return "exists";
    case ManagedPathState::NotFound: return "not_found";
    case ManagedPathState::AccessDenied: return "access_denied";
    case ManagedPathState::Unavailable: return "unavailable";
    case ManagedPathState::Unknown: return "unknown";
    default: return "unknown";
    }
}

