std::wstring Trim(std::wstring text) {
    const auto isSpace = [](wchar_t ch) { return std::iswspace(ch) != 0; };
    text.erase(text.begin(), std::find_if_not(text.begin(), text.end(), isSpace));
    text.erase(std::find_if_not(text.rbegin(), text.rend(), isSpace).base(), text.end());
    return text;
}

std::wstring Shorten(const std::wstring& text, std::size_t maximum) {
    if (text.size() <= maximum) {
        return text;
    }
    if (maximum < 2) {
        return text.substr(0, maximum);
    }
    return text.substr(0, maximum - 1) + L"…";
}

std::wstring FileDisplayName(const std::wstring& path) {
    if (path.empty()) {
        return L"未知文件";
    }
    const wchar_t* filename = PathFindFileNameW(path.c_str());
    if (filename != nullptr && *filename != L'\0') {
        return filename;
    }
    return path;
}

std::wstring MakeDisplayName(const std::wstring& path, bool isDirectory) {
    std::wstring title = FileDisplayName(path);
    if (!isDirectory) {
        const std::size_t separator = title.find_last_of(L'.');
        if (separator != std::wstring::npos && separator > 0) {
            title.resize(separator);
        }
    }
    title = Trim(std::move(title));
    if (title.empty()) {
        title = L"未知文件";
    }
    // Emergency restore destinations append this suffix to avoid overwriting a
    // desktop file.  Keeping its tail visible prevents a restored file from
    // looking identical to the original after the normal 12-character trim.
    constexpr std::wstring_view kRestoreMarker = L"（引力桌面恢复";
    const std::size_t restore = title.find(kRestoreMarker);
    if (restore != std::wstring::npos && title.size() > 12) {
        const std::wstring prefix = Shorten(title.substr(0, restore), 5);
        std::wstring suffix = title.substr(restore);
        if (suffix.size() > 6) {
            suffix = L"恢复" + suffix.substr(kRestoreMarker.size());
        }
        return Shorten(prefix + L"…" + suffix, 12);
    }
    return Shorten(title, 12);
}

bool IsTransientDesktopArtifactName(const std::wstring& path) {
    std::wstring name = FileDisplayName(path);
    std::transform(name.begin(), name.end(), name.begin(),
                   [](wchar_t character) {
                       return static_cast<wchar_t>(std::towlower(character));
                   });
    return name.rfind(L"~$", 0) == 0 || name == L"desktop.ini" ||
           name == L"thumbs.db";
}

int RingForSlot(int slot) {
    for (int ring = 0; ring < static_cast<int>(kRingCapacities.size()); ++ring) {
        if (slot >= kRingStarts[ring] &&
            slot < kRingStarts[ring] + kRingCapacities[ring]) {
            return ring;
        }
    }
    return -1;
}

int RingSlotForSlot(int slot) {
    const int ring = RingForSlot(slot);
    return ring < 0 ? -1 : slot - kRingStarts[ring];
}

int GlobalSlot(int ring, int ringSlot) {
    if (ring < 0 || ring >= static_cast<int>(kRingCapacities.size()) ||
        ringSlot < 0 || ringSlot >= kRingCapacities[ring]) {
        return -1;
    }
    return kRingStarts[ring] + ringSlot;
}

float SlotAngleRadians(int ring, int ringSlot, float angleOffsetDegrees = 0.0f) {
    if (ring < 0 || ring >= static_cast<int>(kRingCapacities.size()) ||
        kRingCapacities[ring] <= 0) {
        return -kPi / 2.0f;
    }
    const float phase =
        -kPi / 2.0f -
        (ring == 0 ? 0.0f
                   : kPi / static_cast<float>(kRingCapacities[ring]));
    return phase +
           2.0f * kPi * static_cast<float>(ringSlot) /
               static_cast<float>(kRingCapacities[ring]) +
           angleOffsetDegrees * kPi / 180.0f;
}

std::array<int, 2> StandardRingCounts(int visibleCount) {
    visibleCount = std::clamp(visibleCount, 0, kPriorityPlacementSlots);
    if (visibleCount <= 6) {
        return {visibleCount, 0};
    }
    const int inner = (visibleCount + 1) / 2;
    return {inner, visibleCount - inner};
}

float StandardAngleDegrees(int ring, int ringSlot,
                           int innerCount, int outerCount) {
    const int count = ring == 0 ? innerCount : outerCount;
    if (count <= 0) {
        return -90.0f;
    }
    const float offset =
        ring == 1 && innerCount > 0
            ? 180.0f / static_cast<float>(innerCount)
            : 0.0f;
    return -90.0f + offset +
           360.0f * static_cast<float>(ringSlot) /
               static_cast<float>(count);
}

std::array<int, 2> TemplateRingCounts(LayoutTemplate layout,
                                      int visibleCount) {
    visibleCount = std::clamp(visibleCount, 0, kCoreFileCapacity);
    switch (layout) {
    case LayoutTemplate::AutoCompact:
        if (visibleCount <= 6) {
            return {visibleCount, 0};
        }
        if (visibleCount <= 15) {
            return {std::min(5, visibleCount), visibleCount - 5};
        }
        return {6, visibleCount - 6};
    case LayoutTemplate::CompactDouble:
        return {std::min(5, visibleCount),
                std::min(10, std::max(0, visibleCount - 5))};
    case LayoutTemplate::HighCapacityDouble:
        return {std::min(6, visibleCount),
                std::min(12, std::max(0, visibleCount - 6))};
    case LayoutTemplate::SingleRing:
        return {visibleCount, 0};
    default:
        return {0, 0};
    }
}

int TemplateVisibleLimit(LayoutTemplate layout) {
    switch (layout) {
    case LayoutTemplate::AutoCompact:
        return 15;
    case LayoutTemplate::CompactDouble:
        return 15;
    case LayoutTemplate::HighCapacityDouble:
        return 18;
    case LayoutTemplate::SingleRing:
        return kCoreFileCapacity;
    default:
        return 0;
    }
}

float TemplateAngleDegrees(LayoutTemplate layout, int ring, int ringSlot,
                           int innerCount, int outerCount) {
    if (layout == LayoutTemplate::CompactDouble ||
        layout == LayoutTemplate::HighCapacityDouble ||
        layout == LayoutTemplate::AutoCompact) {
        const int count = ring == 0 ? innerCount : outerCount;
        if (count <= 0) {
            return -90.0f;
        }
        const float offset = ring == 1 ?
            180.0f / static_cast<float>(outerCount) : 0.0f;
        const float spacing = 360.0f / static_cast<float>(count);
        return -90.0f + offset + spacing * static_cast<float>(ringSlot);
    }
    return StandardAngleDegrees(ring, ringSlot, innerCount, outerCount);
}

int TemplateGlobalSlot(LayoutTemplate layout, int ring, int ringSlot) {
    // SingleRing stores a template-local ordinal in the existing `slot`
    // field. It deliberately does not inherit the standard 6+13 physical
    // ring split: ordinals 0..17 all belong to its one logical ring.
    if (layout == LayoutTemplate::SingleRing) {
        return ring == 0 && ringSlot >= 0 &&
                       ringSlot < kCoreFileCapacity
                   ? ringSlot
                   : -1;
    }
    if (layout == LayoutTemplate::CompactDouble && ring == 0 &&
        ringSlot >= 5) {
        return -1;
    }
    return GlobalSlot(ring, ringSlot);
}

int TemplateRingForSlot(LayoutTemplate layout, int slot) {
    if (layout == LayoutTemplate::SingleRing) {
        return slot >= 0 && slot < kCoreFileCapacity ? 0 : -1;
    }
    return RingForSlot(slot);
}

int TemplateRingSlotForSlot(LayoutTemplate layout, int slot) {
    if (layout == LayoutTemplate::SingleRing) {
        return slot >= 0 && slot < kCoreFileCapacity ? slot : -1;
    }
    return RingSlotForSlot(slot);
}

float NormalizeDegrees(float degrees) {
    degrees = std::fmod(degrees, 360.0f);
    return degrees < 0.0f ? degrees + 360.0f : degrees;
}

std::uint64_t StableHash(std::uint64_t id, const std::wstring& path) {
    std::uint64_t hash = 1469598103934665603ULL ^ id;
    for (const wchar_t ch : path) {
        hash ^= static_cast<std::uint64_t>(std::towlower(ch));
        hash *= 1099511628211ULL;
    }
    return hash;
}

void GenerateStableOffsets(FileItem& item) {
    const std::uint64_t hash = StableHash(item.id, item.path);
    item.angleOffsetDegrees =
        -5.0f + static_cast<float>(hash % 1001ULL) / 1000.0f * 10.0f;
    item.radiusOffset =
        -8.0f + static_cast<float>((hash >> 12) % 1001ULL) / 1000.0f * 16.0f;
}

float TierIconPixels(FileSizeTier tier) {
    switch (tier) {
    case FileSizeTier::Important:
        return 56.0f;
    case FileSizeTier::Minor:
        return 40.0f;
    default:
        return 48.0f;
    }
}

float TierContainerPixels(FileSizeTier tier) {
    switch (tier) {
    case FileSizeTier::Important:
        return 68.0f;
    case FileSizeTier::Minor:
        return 52.0f;
    default:
        return 60.0f;
    }
}

D2D1_SIZE_F TierFootprintPixels(FileSizeTier tier) {
    switch (tier) {
    case FileSizeTier::Important:
        return D2D1::SizeF(104.0f, 112.0f);
    case FileSizeTier::Minor:
        return D2D1::SizeF(84.0f, 92.0f);
    default:
        return D2D1::SizeF(96.0f, 104.0f);
    }
}

bool PathEquals(const std::wstring& first, const std::wstring& second) {
    return CompareStringOrdinal(first.c_str(), -1, second.c_str(), -1, TRUE) == CSTR_EQUAL;
}

std::wstring NormalizePath(const std::wstring& path) {
    const DWORD required = GetFullPathNameW(path.c_str(), 0, nullptr, nullptr);
    if (required == 0) {
        return path;
    }
    std::wstring normalized(static_cast<std::size_t>(required), L'\0');
    const DWORD written = GetFullPathNameW(path.c_str(), required, normalized.data(), nullptr);
    if (written == 0 || written >= required) {
        return path;
    }
    normalized.resize(written);
    return normalized;
}

std::optional<std::filesystem::path> KnownFolderPathForSelfTest(
    REFKNOWNFOLDERID folderId) {
    PWSTR value = nullptr;
    if (FAILED(SHGetKnownFolderPath(
            folderId, KF_FLAG_DEFAULT, nullptr, &value))) {
        return std::nullopt;
    }
    std::filesystem::path result(value);
    CoTaskMemFree(value);
    return result;
}

bool IsPathEqualOrInside(const std::filesystem::path& candidate,
                         const std::filesystem::path& root) {
    const std::wstring normalizedCandidate =
        NormalizePath(candidate.wstring());
    std::wstring normalizedRoot = NormalizePath(root.wstring());
    if (normalizedCandidate.empty() || normalizedRoot.empty()) return false;
    if (PathEquals(normalizedCandidate, normalizedRoot)) return true;
    if (normalizedRoot.back() != L'\\') normalizedRoot.push_back(L'\\');
    return normalizedCandidate.rfind(normalizedRoot, 0) == 0;
}

std::wstring FinalExistingPath(const std::wstring& path) {
    if (path.empty()) return {};
    HANDLE handle = CreateFileW(
        path.c_str(), FILE_READ_ATTRIBUTES,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, nullptr);
    if (handle == INVALID_HANDLE_VALUE) return {};

    std::vector<wchar_t> buffer(32768, L'\0');
    DWORD written = GetFinalPathNameByHandleW(
        handle, buffer.data(), static_cast<DWORD>(buffer.size()),
        FILE_NAME_NORMALIZED);
    if (written >= buffer.size()) {
        buffer.assign(static_cast<std::size_t>(written) + 1, L'\0');
        written = GetFinalPathNameByHandleW(
            handle, buffer.data(), static_cast<DWORD>(buffer.size()),
            FILE_NAME_NORMALIZED);
    }
    CloseHandle(handle);
    if (written == 0 || written >= buffer.size()) return {};

    std::wstring result(buffer.data(), written);
    constexpr std::wstring_view uncPrefix = L"\\\\?\\UNC\\";
    constexpr std::wstring_view extendedPrefix = L"\\\\?\\";
    if (result.rfind(uncPrefix, 0) == 0) {
        result.replace(0, uncPrefix.size(), L"\\\\");
    } else if (result.rfind(extendedPrefix, 0) == 0) {
        result.erase(0, extendedPrefix.size());
    }
    return NormalizePath(result);
}

bool IsFinalPathEqualOrInside(
    const std::wstring& candidate,
    const std::filesystem::path& root) {
    if (candidate.empty() || root.empty()) return false;
    const std::filesystem::path normalizedCandidate(
        NormalizePath(candidate));
    const std::filesystem::path normalizedRoot(
        NormalizePath(root.wstring()));
    if (normalizedCandidate.empty() || normalizedRoot.empty()) return false;

    // The lexical comparison protects the library even when a reparse point
    // inside it redirects somewhere else.  The final-path comparisons catch
    // a junction/symlink outside the library that resolves into it.
    if (IsPathEqualOrInside(normalizedCandidate, normalizedRoot)) return true;

    const std::wstring finalCandidate = FinalExistingPath(candidate);
    if (finalCandidate.empty()) return false;
    if (IsPathEqualOrInside(
            std::filesystem::path(finalCandidate), normalizedRoot)) {
        return true;
    }

    const std::wstring finalRoot = FinalExistingPath(normalizedRoot.wstring());
    return !finalRoot.empty() && IsPathEqualOrInside(
        std::filesystem::path(finalCandidate),
        std::filesystem::path(finalRoot));
}

std::optional<std::wstring> ResolveFileShortcutTarget(
    const std::wstring& shortcutPath) {
    ComPtr<IShellLinkW> shellLink;
    HRESULT result = CoCreateInstance(
        CLSID_ShellLink, nullptr, CLSCTX_INPROC_SERVER,
        IID_PPV_ARGS(shellLink.ReleaseAndGetAddressOf()));
    ComPtr<IPersistFile> persist;
    if (SUCCEEDED(result)) result = shellLink.As(&persist);
    if (SUCCEEDED(result)) result = persist->Load(
        shortcutPath.c_str(), STGM_READ);
    std::array<wchar_t, 32768> target{};
    if (SUCCEEDED(result)) result = shellLink->GetPath(
        target.data(), static_cast<int>(target.size()), nullptr,
        SLGP_RAWPATH);
    if (FAILED(result) || target[0] == L'\0') return std::nullopt;
    return std::wstring(target.data());
}

// A save-dialog target does not yet exist, but its parent does. Resolve that
// directory through the filesystem before comparing it with the managed
// library so a junction cannot be used to write an archive back into it.
std::filesystem::path FinalExistingDirectoryPath(
    const std::filesystem::path& path) {
    HANDLE handle = CreateFileW(path.c_str(), FILE_READ_ATTRIBUTES,
        FILE_SHARE_READ | FILE_SHARE_WRITE | FILE_SHARE_DELETE, nullptr,
        OPEN_EXISTING, FILE_FLAG_BACKUP_SEMANTICS, nullptr);
    // Resolve the existing parent before classifying the destination.  If
    // the filesystem cannot resolve it, fail closed so an inaccessible
    // junction/reparse alias cannot bypass the library guard.
    if (handle == INVALID_HANDLE_VALUE) return {};
    std::wstring value(32768, L'\0');
    const DWORD written = GetFinalPathNameByHandleW(
        handle, value.data(), static_cast<DWORD>(value.size()),
        FILE_NAME_NORMALIZED);
    CloseHandle(handle);
    if (written == 0 || written >= value.size()) return {};
    value.resize(written);
    constexpr std::wstring_view extendedPrefix = L"\\\\?\\";
    if (value.rfind(extendedPrefix, 0) == 0) value.erase(0, extendedPrefix.size());
    return std::filesystem::path(value);
}

bool IsProtectedUserDataPath(const std::filesystem::path& candidate) {
    const auto documents = KnownFolderPathForSelfTest(FOLDERID_Documents);
    const auto localAppData =
        KnownFolderPathForSelfTest(FOLDERID_LocalAppData);
    return (documents.has_value() && IsPathEqualOrInside(
                candidate, *documents / L"Gravity Desktop Files")) ||
           (localAppData.has_value() && IsPathEqualOrInside(
                candidate, *localAppData / L"GravityDesktop"));
}

std::filesystem::path SelfTestTempRoot() {
    wchar_t buffer[MAX_PATH]{};
    const DWORD length = GetTempPathW(
        static_cast<DWORD>(std::size(buffer)), buffer);
    if (length == 0 || length >= std::size(buffer)) return {};
    return std::filesystem::path(buffer);
}

bool ValidateSelfTestPath(const std::filesystem::path& candidate) {
    if (!gRunningSelfTest) return true;
    const std::filesystem::path tempRoot = SelfTestTempRoot();
    const bool safe = !candidate.empty() && !tempRoot.empty() &&
        IsPathEqualOrInside(candidate, tempRoot) &&
        !IsProtectedUserDataPath(candidate);
    if (!safe) gSelfTestPathViolation = true;
    return safe;
}

std::wstring CurrentExecutablePath() {
    // Windows executable paths may exceed MAX_PATH when long-path support is
    // enabled. Keep the registry command exact rather than silently truncating
    // it to an old fixed buffer.
    std::wstring buffer(32768, L'\0');
    const DWORD written = GetModuleFileNameW(
        nullptr, buffer.data(), static_cast<DWORD>(buffer.size()));
    if (written == 0 || written >= buffer.size()) {
        return {};
    }
    buffer.resize(written);
    return NormalizePath(buffer);
}

bool IsPackagedProcess() {
    UINT32 packageFullNameLength = 0;
    const LONG result = GetCurrentPackageFullName(
        &packageFullNameLength, nullptr);
    return result == ERROR_SUCCESS || result == ERROR_INSUFFICIENT_BUFFER;
}

// Both executables are full-trust desktop applications. File activation must
// preserve Shell association/shortcut semantics; WinRT LaunchFileAsync is not
// equivalent for executable files and directories. Keep this boundary limited
// to an explicit existing absolute file path and the standard "open" verb.
struct FileLaunchDiagnostic {
    const char* launcher = "shell_execute";
    const char* stage = "request_created";
    HRESULT result = S_OK;
    DWORD error = ERROR_SUCCESS;
};

bool OpenFileWithSystemLauncher(HWND owner, const std::wstring& path,
                                FileLaunchDiagnostic* diagnostic = nullptr) {
    FileLaunchDiagnostic local;
    auto& outcome = diagnostic != nullptr ? *diagnostic : local;
    outcome = FileLaunchDiagnostic{};
    if (path.empty() || path.find(L'\0') != std::wstring::npos ||
        !std::filesystem::path(path).is_absolute()) {
        outcome.stage = "invalid_file_path";
        outcome.error = ERROR_INVALID_NAME;
        outcome.result = HRESULT_FROM_WIN32(outcome.error);
        return false;
    }
    if (GetFileAttributesW(path.c_str()) == INVALID_FILE_ATTRIBUTES) {
        outcome.error = GetLastError();
        outcome.stage = "file_path_unavailable";
        outcome.result = HRESULT_FROM_WIN32(outcome.error);
        return false;
    }
    SHELLEXECUTEINFOW execute{sizeof(execute)};
    execute.fMask = SEE_MASK_FLAG_NO_UI | SEE_MASK_ASYNCOK;
    execute.hwnd = owner;
    execute.lpVerb = L"open";
    execute.lpFile = path.c_str();
    execute.nShow = SW_SHOWNORMAL;
    outcome.stage = "shell_execute";
    const bool accepted = ShellExecuteExW(&execute) != FALSE;
    outcome.error = accepted ? ERROR_SUCCESS : GetLastError();
    outcome.result = accepted ? S_OK : (outcome.error != ERROR_SUCCESS
        ? HRESULT_FROM_WIN32(outcome.error) : E_FAIL);
    outcome.stage = accepted ? "windows_accepted_request" : "shell_execute_failed";
    return accepted;
}

// Build the exact CF_HDROP payload used by Windows Explorer for a one-item
// file copy.  The payload only describes an existing source path; it has no
// move operation and cannot modify the source by itself.
HGLOBAL CreateFileCopyDropData(std::wstring_view path) {
    if (path.empty()) return nullptr;
    const std::size_t bytes = sizeof(DROPFILES) +
        (path.size() + 2) * sizeof(wchar_t);
    HGLOBAL memory = GlobalAlloc(GMEM_MOVEABLE | GMEM_ZEROINIT, bytes);
    if (memory == nullptr) return nullptr;
    void* locked = GlobalLock(memory);
    if (locked == nullptr) {
        GlobalFree(memory);
        return nullptr;
    }
    auto* drop = static_cast<DROPFILES*>(locked);
    drop->pFiles = sizeof(DROPFILES);
    drop->fWide = TRUE;
    auto* names = reinterpret_cast<wchar_t*>(
        static_cast<std::byte*>(locked) + sizeof(DROPFILES));
    std::memcpy(names, path.data(), path.size() * sizeof(wchar_t));
    names[path.size()] = L'\0';
    names[path.size() + 1] = L'\0';
    GlobalUnlock(memory);
    return memory;
}

bool CopyFileToClipboard(HWND owner, const std::wstring& path) {
    HGLOBAL files = CreateFileCopyDropData(path);
    if (files == nullptr) return false;
    const UINT preferredDropEffect =
        RegisterClipboardFormatW(CFSTR_PREFERREDDROPEFFECT);
    HGLOBAL effect = GlobalAlloc(GMEM_MOVEABLE, sizeof(DWORD));
    if (preferredDropEffect == 0 || effect == nullptr) {
        GlobalFree(files);
        if (effect != nullptr) GlobalFree(effect);
        return false;
    }
    void* lockedEffect = GlobalLock(effect);
    if (lockedEffect == nullptr) {
        GlobalFree(effect);
        GlobalFree(files);
        return false;
    }
    *static_cast<DWORD*>(lockedEffect) = DROPEFFECT_COPY;
    GlobalUnlock(effect);

    if (!OpenClipboard(owner)) {
        GlobalFree(effect);
        GlobalFree(files);
        return false;
    }
    bool copied = false;
    if (EmptyClipboard()) {
        if (SetClipboardData(CF_HDROP, files) != nullptr) {
            files = nullptr;
            if (SetClipboardData(preferredDropEffect, effect) != nullptr) {
                effect = nullptr;
                copied = true;
            } else {
                // Explorer must never infer a cut/move when the explicit copy
                // effect could not be published with the file payload.
                EmptyClipboard();
            }
        }
    }
    CloseClipboard();
    if (files != nullptr) GlobalFree(files);
    if (effect != nullptr) GlobalFree(effect);
    return copied;
}

bool ValidateFileCopyDropData(HGLOBAL memory, std::wstring_view expected) {
    if (memory == nullptr || expected.empty()) return false;
    const SIZE_T bytes = GlobalSize(memory);
    if (bytes < sizeof(DROPFILES) + (expected.size() + 2) * sizeof(wchar_t)) {
        return false;
    }
    const void* locked = GlobalLock(memory);
    if (locked == nullptr) return false;
    const auto* drop = static_cast<const DROPFILES*>(locked);
    const auto* names = reinterpret_cast<const wchar_t*>(
        static_cast<const std::byte*>(locked) + sizeof(DROPFILES));
    const bool valid = drop->pFiles == sizeof(DROPFILES) &&
        drop->fWide == TRUE &&
        std::wstring_view(names, expected.size()) == expected &&
        names[expected.size()] == L'\0' &&
        names[expected.size() + 1] == L'\0';
    GlobalUnlock(memory);
    return valid;
}

bool CopyTextToClipboard(HWND owner, std::wstring_view text) {
    if (text.empty() || !OpenClipboard(owner)) return false;
    bool copied = false;
    if (EmptyClipboard()) {
        const std::size_t bytes = (text.size() + 1) * sizeof(wchar_t);
        HGLOBAL memory = GlobalAlloc(GMEM_MOVEABLE, bytes);
        if (memory != nullptr) {
            void* destination = GlobalLock(memory);
            if (destination != nullptr) {
                std::memcpy(destination, text.data(),
                            text.size() * sizeof(wchar_t));
                static_cast<wchar_t*>(destination)[text.size()] = L'\0';
                GlobalUnlock(memory);
                copied = SetClipboardData(CF_UNICODETEXT, memory) != nullptr;
            }
            if (!copied) GlobalFree(memory);
        }
    }
    CloseClipboard();
    return copied;
}

