        const float width = (card.right - card.left - 28.0f - gap) * 0.5f;
        const float left =
            card.left + 14.0f + static_cast<float>(column) * (width + gap);
        const float top =
            card.top + 381.0f + static_cast<float>(row) * 29.0f;
        return D2D1::RectF(left, top, left + width, top + 24.0f);
